import{_ as o,C as t,o as s,c as i,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/context-authority-20260918/secret-argv.figure.en.svg",f=JSON.parse('{"title":"The secret came from an environment variable. Why was it still in the process list?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The secret came from an environment variable. Why was it still in the process list?","date":"2026-09-18","published_date":"2026-09-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Does sourcing a secret from an environment variable keep it out of child-process command lines?","summary":"One synthetic token, three transport paths, and one process observer show why secret origin and secret transport are different claims.","cover":"/assets/context-authority-20260918/secret-argv.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded Windows synthetic-token experiment; not a Linux incident reproduction","pageClass":"context-authority-article"},"headers":[],"relativePath":"en/research/2026-09-18-secret-origin-vs-transport.md","filePath":"en/research/2026-09-18-secret-origin-vs-transport.md","lastUpdated":1789700812000}'),l={name:"en/research/2026-09-18-secret-origin-vs-transport.md"};function d(p,e,u,m,g,v){const r=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[a(r,{image:"/assets/context-authority-20260918/secret-argv.cover-v1.png",kicker:"Open-source engineering · Security experiment",title:"The secret came from an environment variable. Why was it still in the process list?",summary:"A safe origin does not guarantee a safe path. Expanding a secret into command arguments moves it into a new observation surface.",version:"2026-09-18",languageHref:"/zh/research/2026-09-18-secret-origin-vs-transport",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="the-secret-came-from-an-environment-variable-why-was-it-still-in-the-process-list" tabindex="-1">The secret came from an environment variable. Why was it still in the process list? <a class="header-anchor" href="#the-secret-came-from-an-environment-variable-why-was-it-still-in-the-process-list" aria-label="Permalink to &quot;The secret came from an environment variable. Why was it still in the process list?&quot;">​</a></h1><p>Security instructions often say, “provide the API key through an environment variable.” That sounds like an endpoint. It only describes where the value starts.</p><p>Now consider this command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.test/me</span></span></code></pre></div><p>The shell expands <code>$API_KEY</code> before starting <code>curl</code>. The real token becomes a command-line argument. It began in the environment and then crossed into another observation surface.</p><h2 id="where-the-question-came-from" tabindex="-1">Where the question came from <a class="header-anchor" href="#where-the-question-came-from" aria-label="Permalink to &quot;Where the question came from&quot;">​</a></h2><p>An open Paperclip pull request, <a href="https://github.com/paperclipai/paperclip/pull/13572" target="_blank" rel="noreferrer">#13572</a>, reports a concrete instance. The platform included a copyable <code>curl</code> example in agent prompts that expanded a run JWT into argv. Author Dmitry Novikov says continuous <code>/proc/&lt;pid&gt;/cmdline</code> sampling in a Linux deployment captured live JWTs from working agents. The PR changes prompts and scripts to feed authorization material through stdin.</p><p>The source matters because it challenges a convenient shortcut: “the secret is in an environment variable, so it is not in the command.” The full question is how the value is projected from storage to use.</p><p>We could not reproduce that Linux deployment on our Windows research host, and we did not use a real Paperclip token. We tested a narrower question: when the same synthetic token reaches a waiting child through argv, an environment variable, or stdin, what appears in the Windows process command line?</p><h2 id="one-synthetic-secret-three-paths" tabindex="-1">One synthetic secret, three paths <a class="header-anchor" href="#one-synthetic-secret-three-paths" aria-label="Permalink to &quot;One synthetic secret, three paths&quot;">​</a></h2><p>The token was <code>SYNTHETIC-RUN-TOKEN-9f4c2a</code>. Three child processes received it in different ways:</p><ol><li>argv: as the value of <code>--token</code>;</li><li>env: in a child-process environment variable;</li><li>stdin: written after process creation.</li></ol><p>The parent, running under the same Windows account, read each command line through <code>Win32_Process.CommandLine</code>. The probe made no network request and used no real credential.</p><table tabindex="0"><thead><tr><th>Transport</th><th>Child started</th><th>Token visible in command line</th></tr></thead><tbody><tr><td>argv</td><td>Yes</td><td><strong>Yes</strong></td></tr><tr><td>Environment</td><td>Yes</td><td>No</td></tr><tr><td>stdin</td><td>Yes</td><td>No</td></tr></tbody></table><p><img src="'+h+'" alt="Command-line visibility of the same token over three transports"></p><p><em>Figure 1: only the argv path exposed the synthetic token in the Windows command-line view we tested. This does not establish that environment variables or stdin are inaccessible through every other channel.</em></p><h2 id="the-security-boundary-changed-during-projection" tabindex="-1">The security boundary changed during projection <a class="header-anchor" href="#the-security-boundary-changed-during-projection" aria-label="Permalink to &quot;The security boundary changed during projection&quot;">​</a></h2><p>The environment is the source; argv is a later carrier. Putting <code>$API_KEY</code> in a command template tells the shell to replace the variable with an ordinary string before creating the child process. Whether process listings, diagnostics, crash reports, or audit collectors can then see it depends on the operating system and deployment boundary.</p><p>This is why “no plaintext secret in the repository” and “no runtime secret disclosure” are separate checks. One is about static storage; the other is about the interfaces a value crosses while the program runs.</p><p>stdin is not a universal certificate of secrecy either. It only avoids making the value a target-process argument. The receiving program might log its input, the parent still holds the value, and a sufficiently privileged observer may have other access to memory or environment state. Our result is specifically about command-line visibility.</p><h2 id="what-the-upstream-pr-gets-right-and-what-remains" tabindex="-1">What the upstream PR gets right, and what remains <a class="header-anchor" href="#what-the-upstream-pr-gets-right-and-what-remains" aria-label="Permalink to &quot;What the upstream PR gets right, and what remains&quot;">​</a></h2><p>PR #13572 adds more than a safer snippet. It introduces a regression probe with a red control: first prove that the detector can observe an intentionally leaked argv token, then require zero hits for the corrected path. Without that positive control, a broken sampler could report a false clean result.</p><p>The PR remains open. Its author also identifies follow-up locations, including pinned skill snapshots, smoke scripts, workflows, and documentation. We therefore cannot say that Paperclip has completed a comprehensive fix, and we do not present the author&#39;s Linux measurements as our experiment.</p><h2 id="does-codeflowmu-need-development-work" tabindex="-1">Does CodeFlowMu need development work? <a class="header-anchor" href="#does-codeflowmu-need-development-work" aria-label="Permalink to &quot;Does CodeFlowMu need development work?&quot;">​</a></h2><p>We inspected CodeFlowMu v2.1.2 process-launch paths and found no API key assembled into argv. The Windows Use Host path we examined passes configuration in the environment and sends call data as JSON over stdin; argv contains the Python interpreter, script path, and non-secret startup fields.</p><p>Our development-review decision is <strong>do not implement a change this round</strong>. The finding becomes a security review rule: look for second-stage expansion from env into argv and add a red-control regression when a real call site is found. There is no local defect evidence today.</p><h2 id="four-checks-to-take-back-to-a-project" tabindex="-1">Four checks to take back to a project <a class="header-anchor" href="#four-checks-to-take-back-to-a-project" aria-label="Permalink to &quot;Four checks to take back to a project&quot;">​</a></h2><ol><li>Search for <code>$API_KEY</code> and <code>${TOKEN}</code> embedded in command arguments, not only hard-coded secrets.</li><li>Inspect documentation and agent prompts. Copyable examples become runtime behavior.</li><li>Give leak detectors a positive control so they first prove they can see a deliberate leak.</li><li>Record secret origin and final-hop transport separately.</li></ol><p>A deeper question remains. When an agent can generate arbitrary shell commands, should a platform merely teach an argv-safe pattern, or should the execution layer reject sensitive values in argv? The first reduces mistakes; the second enforces a boundary. Their cost and false-positive profiles deserve separate experiments.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><ul><li><a href="https://github.com/paperclipai/paperclip/pull/13572" target="_blank" rel="noreferrer">Paperclip PR #13572</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-18-context-authority" target="_blank" rel="noreferrer">Public experiment record</a></li></ul>',31))])}const y=o(l,[["render",d]]);export{f as __pageData,y as default};
